import React, {useContext} from 'react'
import logo from '../images/logo_header.png'
import {Link} from 'react-router-dom'
import user_icon from '../images/user.svg'
import AuthContext from './AuthContext'

function Header() {
  const {user} = useContext(AuthContext)
  return (
    <div style={{backgroundColor: 'black'}}>
      <img src={logo} alt='logo' style={{height: 80, marginRight: 25}}></img>
      <Link to='/' style={{textDecoration: 'none', color: 'white', fontSize: '20px', marginRight: 25}}>Home</Link>
      { !user &&
        <Link to='/login' style={{textDecoration: 'none', color: 'white', fontSize: '20px', marginRight: 25}}>Login</Link>
      }
      { user && 
        <Link to='/' style={{textDecoration: 'none', color: 'white', fontSize: '20px', marginRight: 25}}>Logout</Link>
      }

      <Link to='/about' style={{textDecoration: 'none', color: 'white', fontSize: '20px'}}>About</Link>
      <Link to='/account' className='float-end me-4 mt-4' style={{textDecoration: 'none', color: 'white', fontSize: '20px'}}>Profile <img src={user_icon} alt='logo' style={{height: 30}}></img></Link>
    </div>
  )
}

export default Header
